#!/usr/bin/env python3
"""Write INDEX.md from item front matter, projects.yml and archive/CATALOG.csv.

Run from the repo root:
    python3 tools/index.py           write INDEX.md
    python3 tools/index.py --check   exit 1 if INDEX.md is not what it would write
"""

import os
import sys
import urllib.parse

import libtools as lt

INDEX = "INDEX.md"
HEADER = ("<!-- Generated by tools/index.py from item front matter, projects.yml "
          "and archive/CATALOG.csv. Do not edit by hand; run python3 tools/index.py. -->")


def cell(value):
    if isinstance(value, list):
        value = ", ".join(value)
    return (value or "").replace("\\", "\\\\").replace("|", "\\|").replace("\n", " ").strip()


def link(path):
    text = cell(path).replace("[", "\\[").replace("]", "\\]")
    return "[%s](%s)" % (text, urllib.parse.quote(path, safe="/._-~"))


def code(value):
    return "`%s`" % value.replace("|", "\\|") if value else ""


def table(columns, rows):
    if not rows:
        return ["_None yet._"]
    out = ["| " + " | ".join(columns) + " |", "|" + " --- |" * len(columns)]
    out += ["| " + " | ".join(r) + " |" for r in rows]
    return out


def newest_first(rows):
    # rows are (date, path, cells); newest date first, then path A-Z
    rows = sorted(rows, key=lambda r: r[1])
    rows = sorted(rows, key=lambda r: r[0], reverse=True)
    return [r[2] for r in rows]


def build(root="."):
    projects, _ = lt.parse_projects(os.path.join(root, "projects.yml"))
    items = lt.load_items(root)
    _, catalog, _ = lt.read_catalog(os.path.join(root, "archive", "CATALOG.csv"))

    out = [HEADER, "", "# Library index", ""]

    out += ["## Projects", ""]
    prow = []
    for p in sorted(projects, key=lambda p: (p.get("slug", ""), p["_line"])):
        prow.append([cell(p.get("slug")), cell(p.get("name")), cell(p.get("status")),
                     cell(p.get("as_of")), code(p.get("hub", "")), cell(p.get("repo")),
                     cell(p.get("note"))])
    out += table(["Slug", "Name", "Status", "As of", "Hub", "Repo", "Note"], prow) + [""]

    columns = ["Title", "Date", "Type", "Status", "Projects", "Path"]
    for shelf in lt.SHELVES:
        rows = []
        for it in items:
            if it["path"].split("/", 1)[0] != shelf:
                continue
            f = it["fields"]
            date = f.get("date") if isinstance(f.get("date"), str) else ""
            rows.append((date, it["path"],
                         [cell(f.get("title")), cell(date), cell(f.get("type")),
                          cell(f.get("status")), cell(f.get("projects")), link(it["path"])]))
        out += ["## " + shelf, ""] + table(columns, newest_first(rows)) + [""]

    rows = []
    for _, r in catalog:
        path = (r.get("path") or "").strip()
        rows.append(((r.get("date") or "").strip(), path,
                     [cell(r.get("title")), cell(r.get("date")), cell(r.get("type")),
                      cell(r.get("status")), cell(lt.split_semi(r.get("projects"))),
                      code(path)]))
    out += ["## archive", ""] + table(columns, newest_first(rows))

    return "\n".join(out) + "\n"


def stale(root="."):
    """Return None if INDEX.md matches what build() writes, byte for byte; else 'missing' or 'out of date'."""
    try:
        with open(os.path.join(root, INDEX), "rb") as f:
            current = f.read()
    except OSError:
        return "missing"
    return None if current == build(root).encode("utf-8") else "out of date"


def main(argv):
    check = "--check" in argv[1:]
    unknown = [a for a in argv[1:] if a != "--check"]
    if unknown:
        print("usage: python3 tools/index.py [--check]", file=sys.stderr)
        return 2
    if check:
        problem = stale(".")
        if problem:
            print("%s:1: INDEX.md is %s; run python3 tools/index.py" % (INDEX, problem))
            return 1
        return 0
    with open(INDEX, "wb") as f:
        f.write(build(".").encode("utf-8"))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
